import{_ as s,o as i,c as t,a2 as a}from"./chunks/framework.DdtnLau3.js";const k=JSON.parse('{"title":"Quick Start","description":"","frontmatter":{},"headers":[],"relativePath":"guide/quick-start.md","filePath":"guide/quick-start.md"}'),n={name:"guide/quick-start.md"};function o(r,e,p,l,h,d){return i(),t("div",null,[...e[0]||(e[0]=[a(`<h1 id="quick-start" tabindex="-1">Quick Start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick Start&quot;">​</a></h1><h2 id="start-piwork-with-one-command" tabindex="-1">Start Piwork with one command <a class="header-anchor" href="#start-piwork-with-one-command" aria-label="Permalink to &quot;Start Piwork with one command&quot;">​</a></h2><p>Use Linux x86-64 and rootful Docker Engine 28+. One container serves the workbench, administration and first-time setup, with no environment variables or client CLI required:</p><p>This published image includes direct browser entry and web setup.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --detach</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --init</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> piwork-core-quickstart</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    --network</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> host</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    --restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> unless-stopped</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    --stop-timeout</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 60</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    --mount</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> type=bind,src=/var/run/docker.sock,dst=/var/run/docker.sock</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    --volume</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/lib/piwork/quickstart/core:/var/lib/piwork/quickstart/core</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    docker.io/pphboy/piwork-core:0.0.10-024c864cb667-99aec1718558</span></span></code></pre></div><p>On this computer or another computer, open <code>http://SERVER_IP:17891</code> using the server’s actual IP. An empty installation shows Create administrator; an initialized installation shows normal sign-in. No terminal authorization link is required.</p><p>Create the administrator with a password and matching confirmation, then sign in to <strong>Quick setup</strong> in Admin (<code>/admin/setup</code>). Follow the two-step guide: enter the model ID, API type, Base URL and API Key, or choose a saved model, then select <strong>Save and continue</strong>. This saves the model and binds CoreRuntime in sequence. The preparation page updates automatically; when all required components are Ready, select <strong>Open workbench</strong> to enter Piwork. The Agent image is embedded with the server release and supplied automatically; it has no input, selector or advanced override. Model Test is explicit and optional; saving does not call the model. Open the workbench to create a Work, chat, manage files or open Services. Return through Admin <strong>Overview → Quick setup</strong> to change configuration. The topbar <strong>Workbench</strong> link remains available while preparation finishes; the completion action waits for all components. Saved accounts, models and Works survive restart.</p><p>One process serves two HTTP listeners: UI defaults to <code>0.0.0.0:17891</code>, Core to <code>0.0.0.0:17871</code>. Browsers use only UI, including files, events and <code>/services/&lt;workId&gt;/&lt;serviceId&gt;/&lt;port&gt;/</code>; the backend calls Core over fixed loopback HTTP. External Linux CLI connects directly to the server Core port. Change ports only with --ui-port/--core-port. UI accepts actual local IPv4 addresses, localhost, loopback and the machine hostname, validates Host, Origin and CSRF, and ignores Forwarded. Each address needs its own login. HTTP only; no HTTPS, custom domain or reverse proxy configuration. Internal Agent callbacks retain container-reachable mTLS on 7172. User Services publish no host ports. Model endpoints must be reachable from Work networks.</p><p>Hosted Services share the workbench origin and must be trusted: scripts can use the current user’s UI permissions. Apps must support a dynamic Service URL prefix; old root-path apps, images and packages are not rewritten automatically. Services support server-side login using response Cookies, Basic/Bearer, HTTP, SSE and WebSocket. Response Cookies stay on the server, partitioned by browser session and Service; Secure Cookies are not forwarded through the HTTP entry. Apps that read/write document.cookie or Cookie Store (including script-read CSRF Cookies) are not guaranteed to work transparently. Script-written browser Cookies are not isolated across Services on the same IP and are never forwarded upstream. Hard-coded .work URLs, cross-site SSO and upstream HTTPS are outside transparent support. Application CSP/X-Frame-Options remain intact; open an application tab when embedding is denied.</p><p>Optional <a href="/piwork/piwork/install/0.0.10-024c864cb667-99aec1718558/docker-compose.yml">Compose</a> (2.24+) and the <a href="https://github.com/pphboy/piwork/blob/main/examples/single-host/README.md" target="_blank" rel="noreferrer">single-host example</a> open the same web application. CLI is an optional advanced tool. See the <a href="/piwork/guide/installation.html#terminal-operations">operations guide</a> for recovery.</p><details><summary>Build and use the native Linux application</summary><p><a href="/piwork/guide/source-installation.html">Build the current source</a>, then run from the repository root. Released programs also work outside the checkout. Native programs support Linux x86-64 only.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./dist/go/piwork-core</span></span></code></pre></div><p>Core includes administration, the workbench and first-time setup. Its only startup settings are <code>--ui-port</code> (17891), <code>--core-port</code> (17871), and <code>--data-dir</code> (piwork/server under the user configuration directory). <code>--help</code> and <code>--version</code> only display information. Ports must be distinct, within 1–65535 and different from internal RPC 7172. Relative data paths resolve from the working directory.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./dist/go/piwork-core</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --ui-port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 17991</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --core-port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 17971</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --data-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/lib/piwork/custom/core</span></span></code></pre></div><p>Choose one startup command. Open the printed HTTP URL, create the administrator, then configure models and runtime in Admin Quick setup. On a headless server, open that address manually. Ctrl+C stops this installation’s managed Works while preserving data, history and desired state; restart with the same data path.</p><p>The Linux native client starts Desktop by default and connects to an existing Core. Select another Desktop port when the local Core UI already uses 17891. The client requires no Docker and does not start or stop Core.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./dist/go/piwork-cli</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --core</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:17871</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> desktop</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 17901</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-open</span></span></code></pre></div><p>Open <code>http://desktop.localhost:17901/</code> locally. Desktop shares user credentials with terminal commands but has its own default Core preference. Business commands select --core, PIWORK_CORE_URL, saved credentials, then the local default. Closing the browser or CLI does not stop Works. Windows browsers can also access the Linux Core UI.</p></details>`,11)])])}const u=s(n,[["render",o]]);export{k as __pageData,u as default};
